import { test, expect } from '@playwright/test';

test.describe('Navigation Menu Highlight', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should highlight the active menu item', async ({ page }) => {
    const activeMenuItem = await page.getByRole('link', { name: 'Home' }); // Replace 'Home' with the actual active menu item name
    await expect(activeMenuItem).toHaveCSS('background-color', 'rgb(255, 0, 0)'); // Replace with the actual highlight color
  });

  test('should not highlight inactive menu items', async ({ page }) => {
    const inactiveMenuItem = await page.getByRole('link', { name: 'About' }); // Replace 'About' with an actual inactive menu item name
    await expect(inactiveMenuItem).not.toHaveCSS('background-color', 'rgb(255, 0, 0)'); // Replace with the actual highlight color
  });
});
